/** Narrow variants, widest last. Only cut for plates a phone would otherwise
 *  download at full size. */
const VARIANTES: Record<string, readonly (readonly [string, number])[]> = {
  "/edicion/cap-impreso.avif": [["/edicion/cap-impreso-w640.avif", 640], ["/edicion/cap-impreso-w1024.avif", 1024]],
  "/edicion/cap-marca.avif": [["/edicion/cap-marca-w640.avif", 640], ["/edicion/cap-marca-w1024.avif", 1024]],
  "/edicion/cap-producto.avif": [["/edicion/cap-producto-w640.avif", 640], ["/edicion/cap-producto-w1024.avif", 1024]],
  "/edicion/ceguera-figura.avif": [["/edicion/ceguera-figura-w640.avif", 640], ["/edicion/ceguera-figura-w1024.avif", 1024]],
  "/edicion/hero-retablo-completo.avif": [["/edicion/hero-retablo-completo-w640.avif", 640], ["/edicion/hero-retablo-completo-w1024.avif", 1024]],
  "/edicion/hero-retablo.avif": [["/edicion/hero-retablo-w640.avif", 640], ["/edicion/hero-retablo-w1024.avif", 1024]],
  "/edicion/panel-3.avif": [["/edicion/panel-3-w640.avif", 640], ["/edicion/panel-3-w1024.avif", 1024]],
  "/edicion/plano-i-fg.avif": [["/edicion/plano-i-fg-w640.avif", 640], ["/edicion/plano-i-fg-w1024.avif", 1024]],
  "/edicion/plano-ii-fg.avif": [["/edicion/plano-ii-fg-w640.avif", 640], ["/edicion/plano-ii-fg-w1024.avif", 1024]],
  "/edicion/plano-v-fg.avif": [["/edicion/plano-v-fg-w640.avif", 640], ["/edicion/plano-v-fg-w1024.avif", 1024]],
};

/**
 * Props for an <img>: intrinsic size, plus srcset/sizes where variants exist.
 *
 * `sizes` defaults to the common case -- a full-bleed ground on a phone, half
 * the viewport on a desktop -- and callers override it where the element is
 * genuinely smaller. That override matters: `sizes` is a PROMISE to the
 * browser, and one that overstates makes it choose a larger file than it needs.
 * The hero anachronism displays at 172px on a phone and was claiming 100vw, so
 * it pulled the 1100px original every time.
 */
export function medidas(src: string, sizes = "(max-width: 767px) 100vw, 50vw") {
  const m = MEDIDAS[src];
  if (!m) return {};
  const v = VARIANTES[src];
  if (!v) return { width: m[0], height: m[1] };
  const srcSet = [...v.map(([s, w]) => `${s} ${w}w`), `${src} ${m[0]}w`].join(", ");
  return {
    width: m[0],
    height: m[1],
    srcSet,
    sizes,
  };
}
